/**
 * QuickOnboarding — new "Elder Dialogue" onboarding.
 *
 * Flow: prologue → name → elder dialogue (15–30 min, dynamic MCQ) → reading
 *       → finish (writes profile + assessment, opens app fresh)
 *
 * Replaces the old quick/deep split + 80-session pre-journey + 32 mirror
 * checkpoints. The reading is generated by the `elder-dialogue` edge function.
 */
import { useState, useCallback, useEffect, useRef } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { motion, AnimatePresence } from "framer-motion";
import { supabase } from "@/lib/supabase";
import { useUpdateAssessment } from "@/hooks/useConsciousnessEngine";
import { useAssessStartingLevels } from "@/hooks/usePracticeMatrix";
import { useForceDarkMode } from "@/hooks/useForceDarkMode";
import PhilosophyPrologue from "@/components/onboarding/PhilosophyPrologue";
import BirthDetails from "@/components/onboarding/BirthDetails";
import ElderDialogue, { type ElderReading as Reading, type ElderTurn } from "@/components/onboarding/elder/ElderDialogue";
import ElderReadingScreen from "@/components/onboarding/elder/ElderReading";
import ElderAnalyzing from "@/components/onboarding/elder/ElderAnalyzing";
import ElderJourneyChoice from "@/components/onboarding/elder/ElderJourneyChoice";
import LifestylePersonalization, { type LifestyleAnswers } from "@/components/onboarding/LifestylePersonalization";
import DayPlanOnboarding from "@/components/onboarding/DayPlanOnboarding";
import { finishElderOnboarding } from "@/lib/onboarding/finishElder";
import { APP_LANGUAGES } from "@/data/languages";
import { preloadLanguage } from "@/lib/i18n";
import { persistLanguageToProfile } from "@/lib/languageProfile";
import { setStoredLanguage, getStoredLanguage } from "@/lib/languagePreference";

interface QuickOnboardingProps {
  userId: string;
  onComplete: () => void;
}

type Step = "prologue" | "name" | "birth" | "language" | "dayplan" | "lifestyle" | "dialogue" | "analyzing" | "reading" | "journey";

export default function QuickOnboarding({ userId, onComplete }: QuickOnboardingProps) {
  useForceDarkMode();
  const progressKey = `quick_onboarding_${userId}`;

  // Hydrate from localStorage so a user who closes mid-onboarding
  // returns exactly where they left off.
  const initial = (() => {
    try {
      const raw = localStorage.getItem(progressKey);
      if (raw) return JSON.parse(raw) as { step?: Step; name?: string; lifestyle?: LifestyleAnswers | null };
    } catch { /* ignore */ }
    return {};
  })();

  const [step, setStep] = useState<Step>(initial.step ?? "prologue");
  const [name, setName] = useState(initial.name ?? "");
  const [lifestyle, setLifestyle] = useState<LifestyleAnswers | null>(initial.lifestyle ?? null);
  const [reading, setReading] = useState<Reading | null>(null);
  const [history, setHistory] = useState<ElderTurn[]>([]);
  const [saving, setSaving] = useState(false);
  const [languageQuery, setLanguageQuery] = useState("");

  // Save progress on every change so refresh / close resumes here.
  useEffect(() => {
    try {
      localStorage.setItem(progressKey, JSON.stringify({ step, name, lifestyle }));
    } catch { /* ignore */ }
  }, [progressKey, step, name, lifestyle]);

  const updateAssessment = useUpdateAssessment();
  const assessStartingLevels = useAssessStartingLevels();
  const queryClient = useQueryClient();

  const handleFinish = useCallback(async (chosenPath: Reading["recommendedPath"]) => {
    if (!reading) return;
    setSaving(true);
    try {
      await finishElderOnboarding({
        userId,
        name,
        reading,
        history,
        chosenPath,
        lifestyle: lifestyle || undefined,
        updateAssessment,
        assessStartingLevels,
        queryClient,
      });
      try { localStorage.removeItem(progressKey); } catch { /* ignore */ }
      onComplete();
    } catch (e) {
      console.error("QuickOnboarding finish failed", e);
      setSaving(false);
    }
  }, [reading, history, name, lifestyle, userId, updateAssessment, assessStartingLevels, queryClient, onComplete, progressKey]);

  // ── Render steps ───────────────────────────────────────────
  if (step === "prologue") {
    return <PhilosophyPrologue onComplete={() => setStep("name")} />;
  }

  if (step === "birth") {
    return (
      <BirthDetails
        userId={userId}
        name={name}
        onComplete={() => {
          // The first-run language gate already asked for a language on this
          // device. Reuse it instead of asking twice, but make sure the
          // profile carries the choice for cross-device continuity.
          const stored = getStoredLanguage();
          if (stored) {
            void preloadLanguage(stored);
            void persistLanguageToProfile(stored, userId);
          }
          setStep(stored ? "dayplan" : "language");
        }}
      />
    );
  }

  if (step === "language") {
    return (
      <LanguageStep
        name={name}
        userId={userId}
        languageQuery={languageQuery}
        setLanguageQuery={setLanguageQuery}
        onSelected={() => setStep("dayplan")}
      />
    );
  }

  if (step === "dayplan") {
    return (
      <DayPlanOnboarding
        userId={userId}
        onComplete={() => setStep("dialogue")}
        onSkip={() => setStep("dialogue")}
      />
    );
  }

  // Lifestyle personalization screens removed per user request — engines
  // run on safe defaults until/unless we surface them in Settings later.

  if (step === "dialogue") {
    return (
      <ElderDialogue
        userId={userId}
        name={name}
        onComplete={(r, h) => {
          setReading(r);
          setHistory(h);
          setStep("analyzing");
        }}
        onPause={async (h) => {
          // Persist a minimal profile so AppEntry lets the user into Home.
          // The Elder dialogue conversation stays in localStorage so the
          // resume banner on Home can pick up where the user left off.
          try {
            await supabase.from("profiles").upsert(
              {
                user_id: userId,
                display_name: name || "Friend",
                onboarded: true,
                onboarding_path: "elder_paused",
              } as any,
              { onConflict: "user_id" }
            );
            localStorage.setItem(`elder_paused_${userId}`, JSON.stringify({ name, turns: h.length }));
            localStorage.setItem(`first_session_done_${userId}`, "1");
          } catch (e) {
            console.warn("Pause persist failed", e);
          }
          onComplete();
        }}
      />
    );
  }

  if (step === "analyzing") {
    return (
      <ElderAnalyzing
        reading={reading}
        name={name}
        onContinue={() => setStep("reading")}
      />
    );
  }

  if (step === "reading" && reading) {
    return (
      <ElderReadingScreen
        reading={reading}
        name={name}
        saving={saving}
        onAccept={() => handleFinish(reading.recommendedPath)}
      />
    );
  }

  // step === "name"
  return (
    <div className="min-h-[100dvh] w-full relative overflow-hidden flex items-center justify-center p-6">

      <div className="w-full max-w-md relative z-10">
        <AnimatePresence mode="wait">
          <motion.div
            key="name"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.5 }}
            className="text-center"
          >
            <p className="text-muted-foreground text-xs uppercase tracking-[0.3em] mb-3">First</p>
            <h2 className="font-display text-2xl text-foreground mb-3">What should we call you?</h2>
            <div className="mb-6" />
            <input
              type="text"
              autoFocus
              value={name}
              onChange={(e) => setName(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter" && name.trim()) setStep("birth"); }}
              placeholder="Your name"
              className="w-full px-5 py-3 bg-card/40 border border-border/40 rounded-xl text-center text-lg text-foreground placeholder:text-muted-foreground/50 focus:outline-none focus:border-primary/60 mb-6"
            />
            <button
              onClick={() => setStep("birth")}
              disabled={!name.trim()}
              className="px-8 py-3 bg-primary text-primary-foreground rounded-full font-display tracking-wide disabled:opacity-30 hover:bg-primary/90 transition"
            >
              Continue
            </button>
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
}

// ─── Language step with keyboard nav (↑/↓ to move, Enter to select, Esc to clear) ───
interface LanguageStepProps {
  name: string;
  userId: string;
  languageQuery: string;
  setLanguageQuery: (s: string) => void;
  onSelected: () => void;
}

function LanguageStep({ name, userId, languageQuery, setLanguageQuery, onSelected }: LanguageStepProps) {
  const langQuery = languageQuery.trim().toLowerCase();
  const filteredLanguages = langQuery
    ? APP_LANGUAGES.filter(
        (l) =>
          l.label.toLowerCase().includes(langQuery) ||
          l.nativeLabel.toLowerCase().includes(langQuery) ||
          l.code.toLowerCase().includes(langQuery)
      )
    : APP_LANGUAGES;

  const [highlight, setHighlight] = useState(0);
  const listRef = useRef<HTMLDivElement>(null);
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);

  // Reset highlight when filter changes
  useEffect(() => { setHighlight(0); }, [langQuery]);

  // Scroll highlighted item into view
  useEffect(() => {
    const el = itemRefs.current[highlight];
    if (el) el.scrollIntoView({ block: "nearest" });
  }, [highlight]);

  const persistLanguage = async (code: string) => {
    setStoredLanguage(code);
    void preloadLanguage(code);
    await persistLanguageToProfile(code, userId);
    onSelected();
  };

  const handleKey = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setHighlight((h) => Math.min(h + 1, filteredLanguages.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlight((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      const lang = filteredLanguages[highlight];
      if (lang) persistLanguage(lang.code);
      else if (languageQuery === "") persistLanguage("en");
    } else if (e.key === "Escape") {
      if (languageQuery) {
        e.preventDefault();
        setLanguageQuery("");
      }
    } else if (e.key === "Home") {
      e.preventDefault();
      setHighlight(0);
    } else if (e.key === "End") {
      e.preventDefault();
      setHighlight(filteredLanguages.length - 1);
    }
  };

  return (
    <div
      className="min-h-[100dvh] w-full relative overflow-hidden flex items-center justify-center p-6"
      onKeyDown={handleKey}
    >

      <div className="w-full max-w-md relative z-10">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="text-center"
        >
          <p className="text-muted-foreground text-xs uppercase tracking-[0.3em] mb-3">Hello, {name}</p>
          <h2 className="font-display text-2xl text-foreground mb-3">In which language shall we sit together?</h2>
          <p className="text-muted-foreground text-sm mb-6 px-4">
            Everything from here — the Elder, your guides, your reflections — will speak in this tongue. You can change it later in Settings.
          </p>
          <input
            type="text"
            autoFocus
            value={languageQuery}
            onChange={(e) => setLanguageQuery(e.target.value)}
            placeholder="Search language…  (↑↓ to navigate, Enter to select)"
            aria-label="Search language"
            className="w-full mb-3 px-4 py-2.5 rounded-lg bg-card/40 border border-border/40 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:border-primary/60 transition"
          />
          <div
            ref={listRef}
            className="max-h-[55vh] overflow-y-auto rounded-xl border border-border/40 bg-card/40 p-1 mb-4"
          >
            {filteredLanguages.length === 0 ? (
              <p className="px-4 py-6 text-sm text-muted-foreground text-center">No languages match "{languageQuery}".</p>
            ) : (
              filteredLanguages.map((lang, i) => (
                <button
                  key={lang.code}
                  ref={(el) => (itemRefs.current[i] = el)}
                  onClick={() => persistLanguage(lang.code)}
                  onMouseEnter={() => setHighlight(i)}
                  className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-left text-sm font-body text-foreground transition ${
                    i === highlight ? "bg-primary/15" : "hover:bg-primary/10"
                  }`}
                >
                  <span className="flex-1">{lang.nativeLabel}</span>
                  <span className="text-xs text-muted-foreground">{lang.label}</span>
                </button>
              ))
            )}
          </div>
          <div className="flex items-center justify-between text-[10px] text-muted-foreground/70 mb-3 px-1">
            <span>↑↓ navigate</span>
            <span>Enter select</span>
            <span>Esc clear</span>
          </div>
          <button
            onClick={() => persistLanguage("en")}
            className="text-xs text-muted-foreground hover:text-foreground transition"
          >
            Continue in English
          </button>
        </motion.div>
      </div>
    </div>
  );
}
